head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBndListProcsTpCd = "1";
scwin.vMktactCd = "202";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(pnl_Item);
        $c.bns.BnsPanelToGroupBox(pnl_Search);
        $c.bns.BnsPanelToGroupBox(pnl_Group);
        // BnsPanelToGroupBox(pnl_NotAppoint);
        // BnsPanelToGroupBox(pnl_Appoint);
        $c.bns.BnsPanelToGroupBox(pnl_Fee);

        // 발행기관 조회
        scwin.setComboIsurNm();
        // 면제사유코드
        scwin.setComboCode();

        // 면제사유 비활성화
        cmb_ListFeeExamptFsnCd.setDisabled(true);

        // 가우스헤더 셋팅(그리드 행 복사 대상)
        const sbmOptions = {
            id : "sbm_dts_CopyList",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_CopyList=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 가우스헤더 셋팅(입력항목)
        // dts_InputItem.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_FEE_ANULFEE_INSERT_INFO";
        // dts_InputItem.Reset();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS11101.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_InputItem_OnLoadCompleted
 * @description dts_InputItem 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_InputItem_OnLoadCompleted = function(rowcount) {
    try {
        // 담당자명이 비어 있는 경우, 사용자 이름을 보여줌
        if (txb_ChrgNm.getValue() === '') {
            txb_ChrgNm.setValue(js_emp_nm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS11101.dts_InputItem_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_IsurItem_OnLoadError
 * @description dts_IsurItem 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_IsurItem_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_IsurItem);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS11101.dts_IsurItem_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_IsurItem_OnLoadCompleted
 * @description dts_IsurItem 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_IsurItem_OnLoadCompleted = function(rowcount) {
    try {
        dts_IsurItem.insertRow(dts_IsurItem.getRowPosition() - 1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS11101.dts_IsurItem_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name cmb_IsurNm_onselchange
 * @description cmb_IsurNm onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_IsurNm_onselchange = function() {
    try {
        scwin.vIsurCd = cmb_IsurNm.BindColVal;
        scwin.listSync();
        scwin.feeSync();
        // dts_InputItem.Reset();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS11101.cmb_IsurNm_onselchange" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        let arrPnl = [pnl_NotAppoint];
        $c.bns.CloseWinArrPnl(rowcount, arrPnl, grd_List1);
        dts_CopyList.removeAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS11101.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_ToRight_onclick
 * @description btn_ToRight 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ToRight_onclick = async function() {
    try {
        await scwin.leftCopy("One");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS11101.btn_ToRight_onclick" });
    }
};

/**
 * @method
 * @name btn_ToRightAll_onclick
 * @description btn_ToRightAll 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ToRightAll_onclick = async function() {
    try {
        dts_CopyList.removeAll();
        await scwin.leftCopy("All");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS11101.btn_ToRightAll_onclick" });
    }
};

/**
 * @method
 * @name btn_ToLeft_onclick
 * @description btn_ToLeft 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ToLeft_onclick = function() {
    try {
        scwin.rightDel("One");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS11101.btn_ToLeft_onclick" });
    }
};

/**
 * @method
 * @name btn_ToLeftAll_onclick
 * @description btn_ToLeftAll 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ToLeftAll_onclick = function() {
    try {
        scwin.rightDel("All");
        dts_InputItem.Reset();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS11101.btn_ToLeftAll_onclick" });
    }
};

/**
 * @method
 * @name img_FeeDepoDd_onclick
 * @description img_FeeDepoDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FeeDepoDd_onclick = function() {
    try {
        popUpCalendar2(edt_FeeDepoDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS11101.img_FeeDepoDd_onclick" });
    }
};

/**
 * @method
 * @name cmb_ChgListFeeFupayYn_onselchange
 * @description cmb_ChgListFeeFupayYn onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_ChgListFeeFupayYn_onselchange = function() {
    try {
        if (cmb_ChgListFeeFupayYn.getValue() === "E") {
            cmb_ListFeeExamptFsnCd.setDisabled(true);
        } else {
            cmb_ListFeeExamptFsnCd.setDisabled(true);
            cmb_ListFeeExamptFsnCd.setValue('');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS11101.cmb_ChgListFeeFupayYn_onselchange" });
    }
};

/**
 * @method
 * @name btn_FeeReg_onclick
 * @description 「수수료등록」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_FeeReg_onclick = async function() {
    try {
        await scwin.insert();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS11101.btn_FeeReg_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS11101.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS11101.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS11101.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name edt_ListFee_OnKillFocus
 * @description edt_ListFee 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.edt_ListFee_OnKillFocus = function() {
    try {
        edt_ListFee.RightMargin = 5;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS11101.edt_ListFee_OnKillFocus" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setComboIsurNm
 * @description 콤보데이터 정의 (그룹지정할 발행기관명)
 * @returns {void}
 * @hidden N
 */
scwin.setComboIsurNm = function() {
    let dsNm = 'BNS_COM_CD';
    let qryId = 'lds.stf.bnschg.select.listGroupingIsurNmChg';
    let param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    $c.bns.fn_SearchBns('ULDBNS11101.xml', dts_IsurItem, dsNm, qryId, param);
};

/**
 * @method
 * @name setComboCode
 * @description 콤보데이터 정의 (채권상장수수료면제사유코드)
 * @returns {void}
 * @hidden N
 */
scwin.setComboCode = function() {
    $c.bns.fn_SetBnsCombo('ULDBNS11101.xml', dts_ListFeeExamptFsnCd, '03385');
};

/**
 * @method
 * @name listSync
 * @description 리스트 데이터를 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    let dsNm = 'BNS_GROUPPING_ISU_INFO';
    let qryId = 'lds.stf.bnschg.select.listSelectedIsurNmChg';
    let param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    param += '&{P}V_ISUR_CD=' + scwin.vIsurCd;
    $c.bns.fn_SearchBns('ULDBNS11101.xml', dts_List, dsNm, qryId, param);
    let arrPnl = [pnl_NotAppoint];
    $c.bns.ShowWinArrPnl(arrPnl, grd_List1);
};

/**
 * @method
 * @name feeSync
 * @description 수수료 데이터를 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.feeSync = function() {
    let dsNm = 'BNS_FEE_ANULFEE_INSERT_INFO';
    let qryId = 'lds.stf.bnschg.select.listSelectedIsurFee';
    let param = '&{P}V_ISUR_CD=' + scwin.vIsurCd;
    $c.bns.fn_SearchBns('ULDBNS11101.xml', dts_InputItem, dsNm, qryId, param);
};

/**
 * @method
 * @name leftCopy
 * @description 그리드 행 복사 (좌 → 우)
 * @param {*} Type Type
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.leftCopy = async function(Type) {
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        if ((Type === 'One') && (dts_List.RowMark(i) === 1)) {
            if (await scwin.copyDuplCheck() === false) return;
            dts_CopyList.insertRow();
            for (let j = 1; j <= dts_List.getTotalCol(); j++) {
                dts_CopyList.setCellData(dts_CopyList.getRowPosition(), j, dts_List.getCellData(i, j));
            }
        }
        if ((Type === 'All')) {
            if (dts_CopyList.getRowCount() !== dts_List.getRowCount()) {
                dts_CopyList.insertRow();
                for (let j = 1; j <= dts_List.getTotalCol(); j++) {
                    dts_CopyList.setCellData(i, j, dts_List.getCellData(i, j));
                }
            }
        }
    }
};

/**
 * @method
 * @name copyDuplCheck
 * @description 그리드 행 복사 시, 중복체크 (return: String)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.copyDuplCheck = async function() {
    const curRowVal = dts_List.getCellData(dts_List.getRowPosition(), "BND_APPL_ID");
    for (let i = 1; i <= dts_CopyList.getRowCount(); i++) {
        if (curRowVal === dts_CopyList.getCellData(i, "BND_APPL_ID")) {
            await $c.win.alert("이미 선택된 종목입니다.");
            return false;
        }
    }
};

/**
 * @method
 * @name rightDel
 * @description 그리드 행 제거
 * @param {*} Type Type
 * @returns {void}
 * @hidden N
 */
scwin.rightDel = function(Type) {
    dts_CopyList.setBroadcast(false);
    for (let i = 1; i <= dts_CopyList.getRowCount(); i++) {
        if ((Type === 'All') || (Type === 'One') && (dts_CopyList.RowMark(i) === 1)) {
            if (Type === 'One') dts_CopyList.removeRow(dts_CopyList.getRowPosition());
            if (Type === 'All') dts_CopyList.removeAll();
        }
    }
    dts_CopyList.setBroadcast(true, true);
};

/**
 * @method
 * @name inputCheck
 * @description 필수 입력 값을 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.inputCheck = async function() {
    if (dts_CopyList.getRowCount() === 0) {
        await $c.win.alert("지정된 종목이 없습니다.");
        return false;
    }
    if (txb_FeeGrpNm.getValue() === '') {
        await $c.win.alert("[그룹명]을 입력하십시오.");
        txb_FeeGrpNm.focus();
        return;
    }
    // 자리수 체크
    if (!$c.stf.checkMaxLength(txb_FeeGrpNm, 30, '그룹명')) return false;
    if (!$c.stf.checkMaxLength(txb_ChrgNm, 80, '담당자')) return false;
    if (cmb_ChgListFeeFupayYn.getValue() === '') {
        await $c.win.alert("[변경상장수수료 납부여부]를 선택하십시오.");
        cmb_ChgListFeeFupayYn.focus();
        return;
    }
    if (cmb_ChgListFeeFupayYn.getValue() === "E" && cmb_ListFeeExamptFsnCd.getValue() === '') {
        await $c.win.alert("변경상장수수료 면제시에는 [면제사유]를 선택하십시오.");
        cmb_ListFeeExamptFsnCd.focus();
        return;
    }

    // 면제가 아닐경우, 입금일 체크
    if (cmb_ChgListFeeFupayYn.getValue() !== "E") {
        if (edt_FeeDepoDd.getValue() === '') {
            await $c.win.alert("상장수수료 면제가 아닌 경우, 입금일을 입력하십시오.");
            return false;
        }
        if (edt_FeeDepoDd.getValue() > scwin.vCurDate) {
            await $c.win.alert("입금일은 오늘 이후 날짜를 입력하실 수 없습니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name insert
 * @description 변경상장 수수료 등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function() {
    // 필수 입력 값 체크
    if (await scwin.inputCheck() === false) return;
    const vAnswer = confirm('변경상장수수료를 등록하시겠습니까?');
    if (vAnswer === true) {
        /*
            //필수 입력항목
			var vFeeGrpNm = getObjectValue(txb_FeeGrpNm);
			var vChgListFeeFupayYn = getObjectValue(cmb_ChgListFeeFupayYn);

            //비 필수 입력항목(공백처리)
			var vListFeeExamptFsnCd = getObjectValue(cmb_ListFeeExamptFsnCd);
			var vFeeDepoDd = getObjectValue(edt_FeeDepoDd);
			var vChrgNm = getObjectValue(txb_ChrgNm);

            //binding 되어 있지 않은 값들을 dts_InputItem에 저장
			dts_InputItem.AddRow();
dts_InputItem.setNameValue(1,"FEE_GRP_NM",vFeeGrpNm) ; 	//수수료그룹명
dts_InputItem.setNameValue(1,"CHG_LIST_FEE_FUPAY_YN",vChgListFeeFupayYn) ; 	//변경상장수수료완납여부
dts_InputItem.setNameValue(1,"BND_CHG_LIST_FEE_EXMPT_RSN_CD",vListFeeExamptFsnCd) ; 	//채권변경상장수수료면제사유코드
dts_InputItem.setNameValue(1,"FEE_DEPO_DD",vFeeDepoDd) ; 	//수수료입금일자
dts_InputItem.setNameValue(1,"CHRG_NM",vChrgNm) ; 	//담당자명
         */

        let url = "/bns/ChgList.do?method=createGrpDesignFee";
        url += "&SCREN_ID=" + 'ULDBNS11101.xml';
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.Action = $c.lc.fn_encodeNSession(url);
        trs_Save.KeyValue = "JSP(I:pInput=dts_InputItem, I:pInput2=dts_CopyList)";
        trs_Save.Post();
    }
};
